export type InterviewFormat = 'knowledge' | 'scenario' | 'system-design' | 'project';
export type InterviewDifficulty = 'easy' | 'medium' | 'hard';

export interface InterviewCatalogItem {
  id: string;
  question: string;
  primaryRole: string;
  roles: string[];
  category: string;
  format: InterviewFormat;
  difficulty: InterviewDifficulty;
  tags: string[];
  keyPoints: string[];
  referenceAnswer: string;
  followUps: string[];
}

interface InterviewSeed extends Omit<InterviewCatalogItem, 'roles' | 'referenceAnswer'> {
  relatedRoles?: string[];
  answerFocus: string;
}

function createItem(seed: InterviewSeed): InterviewCatalogItem {
  const { relatedRoles = [], answerFocus, ...item } = seed;

  return {
    ...item,
    roles: [item.primaryRole, ...relatedRoles.filter((role) => role !== item.primaryRole)],
    referenceAnswer: answerFocus,
  };
}

type ExpansionEntry = readonly [
  category: string,
  format: InterviewFormat,
  difficulty: InterviewDifficulty,
  question: string,
  tags: string[],
  keyPoints: string[],
  answer: string,
  followUp: string,
  relatedRoles?: string[],
];

function expandRoleSeeds(
  primaryRole: string,
  idPrefix: string,
  firstIndex: number,
  entries: ExpansionEntry[],
): InterviewSeed[] {
  return entries.map((entry, offset) => ({
    id: `${idPrefix}-${String(firstIndex + offset).padStart(3, '0')}`,
    primaryRole,
    category: entry[0],
    format: entry[1],
    difficulty: entry[2],
    question: entry[3],
    tags: entry[4],
    keyPoints: entry[5],
    answerFocus: entry[6],
    followUps: [entry[7]],
    relatedRoles: entry[8],
  }));
}

