    '先用文件哈希删除完全重复，再计算 pHash 或其他感知指纹识别缩放、轻微压缩和色彩变化；对裁剪、加框和局部编辑，用视觉嵌入近邻召回候选并结合几何匹配复核。去重关系形成图后按连通簇整体分配到训练、验证或测试，图文配对的不同标题也不能拆散。阈值应在人工抽样上校准，既报告泄漏残留率，也检查过度去重是否错误删除同类但独立的真实样本。',
